INSERT INTO public."Recipe" VALUES
	('cmwhg8rc4007l7dcmw26n3t7c', 'cmwhg8qtv001u7dcm5k1xwbc4', 'Crema hidratante de karité', 100.0000, '1) Calentar fase oleosa (karité, almendras, cera) a 70 °C. 2) Calentar agua y glicerina a 70 °C. 3) Emulsionar. 4) Bajo 40 °C agregar vitamina E, conservante y lavanda. 5) Envasar, tapar y etiquetar.', false, '2026-11-15 06:24:12.389', '2026-11-15 06:24:12.389'),
	('cmwhg8rch007z7dcm8b1i8gq1', 'cmwhg8qty001v7dcm6uvy5m8h', 'Bálsamo labial', 100.0000, 'Fundir cera y mantecas a baño maría, agregar aceite y vitamina E, llenar tubos en caliente y etiquetar.', false, '2026-11-15 06:24:12.402', '2026-11-15 06:24:12.402'),
	('cmwhg8rcr00887dcmcjn7co4r', 'cmwhg8qu2001w7dcmz5i17ibz', 'Jabón artesanal de avena (proceso en frío)', 20.0000, 'Disolver la soda en agua (con protección), mezclar con los aceites a traza, agregar avena, moldear y curar 4 semanas antes de empacar.', false, '2026-11-15 06:24:12.412', '2026-11-15 06:24:12.412'),
	('cmwhg8rd3008h7dcm7x39zbwy', 'cmwhg8qu5001x7dcm7o51kgm4', 'Serum facial vitamina C', 50.0000, 'Hidratar el ácido hialurónico, disolver la vitamina C en agua y glicerina, unir, agregar conservante, envasar en gotero, etiquetar y encajar.', false, '2026-11-15 06:24:12.424', '2026-11-15 06:24:12.424');
